describe('calculator', () => {
  it('adds two numbers', () => {
    expect(2 + 2).to.equal(4);
  });
});

describe('home page', () => {
  it('opens the site', () => {
    cy.visit('https://example.cypress.io');
    cy.get('.navbar').should('be.visible');
  });
});

it('locates elements by selector', () => {
  cy.visit('/login');
  cy.get('#email').type('user@example.com');
  cy.get('.login-form button').click();
});

it('finds elements by their text', () => {
  cy.visit('/products');
  cy.contains('Add to cart').click();
  cy.contains('.card', 'Wireless Mouse').should('be.visible');
});

it('searches inside a container', () => {
  cy.visit('/todos');
  cy.get('.todo-list').find('li').should('have.length', 3);
  cy.get('form').within(() => {
    cy.get('input').type('Buy milk');
  });
});

it('types a search term', () => {
  cy.visit('/search');
  cy.get('#query').type('cypress');
  cy.get('#query').should('have.value', 'cypress');
});

it('clicks the submit button', () => {
  cy.visit('/signup');
  cy.contains('button', 'Create account').click();
  cy.get('#welcome').should('be.visible');
});

it('toggles the newsletter option', () => {
  cy.visit('/settings');
  cy.get('#newsletter').check();
  cy.get('#newsletter').uncheck();
  cy.get('#email').clear();
});

it('selects a role from the dropdown', () => {
  cy.visit('/users/new');
  cy.get('#role').select('admin');
  cy.get('#role').should('have.value', 'admin');
});

it('shows the error banner', () => {
  cy.visit('/checkout');
  cy.get('.error-banner').should('be.visible');
  cy.get('.error-banner').should('have.text', 'Payment failed');
});

it('renders the total price', () => {
  cy.visit('/cart');
  cy.get('#total').should('have.text', '$42.00');
  cy.get('#total').should('not.have.text', '');
});

it('renders three featured products', () => {
  cy.visit('/');
  cy.get('.product-card').should('have.length', 3);
  cy.get('.product-card').first().should('contain', 'Pro');
});

it('waits for the users request', () => {
  cy.intercept('GET', '/api/users').as('getUsers');
  cy.visit('/users');
  cy.wait('@getUsers').its('response.statusCode').should('eq', 200);
});

it('stubs the profile response', () => {
  cy.intercept('GET', '/api/profile', (req) => {
    req.reply({ statusCode: 200, body: { name: 'Ada' } });
  }).as('getProfile');
  cy.visit('/profile');
  cy.wait('@getProfile');
});

it('loads users from a fixture', () => {
  cy.fixture('users.json').then((users) => {
    cy.visit('/users');
    cy.get('.user-row').should('have.length', users.length);
  });
});

it('creates a user through the API', () => {
  cy.request('POST', '/api/users', { name: 'Grace', role: 'admin' }).then((response) => {
    expect(response.status).to.eq(201);
    expect(response.body.name).to.eq('Grace');
  });
});

beforeEach(() => {
  cy.session('admin', () => {
    cy.request('POST', '/api/login', {
      email: 'admin@example.com',
      password: 'secret',
    }).then((response) => {
      window.localStorage.setItem('token', response.body.token);
    });
  });
  cy.visit('/dashboard');
});

Cypress.Commands.add('login', (email, password) => {
  cy.session(email, () => {
    cy.visit('/login');
    cy.get('#email').type(email);
    cy.get('#password').type(password);
  });
});

describe('dashboard', () => {
  beforeEach(() => {
    cy.visit('/login');
    cy.get('#email').type('user@example.com');
    cy.get('#password').type('secret');
    cy.contains('button', 'Log in').click();
  });

  it('shows the stats panel', () => {
    cy.get('.stats').should('be.visible');
  });
});

it('renders the mobile layout', () => {
  cy.viewport('iphone-x');
  cy.visit('/');
  cy.get('.mobile-menu').should('be.visible');
});

it('advances the countdown timer', () => {
  cy.clock();
  cy.visit('/flash-sale');
  cy.tick(60000);
  cy.get('#timer').should('have.text', '00:00');
});

it('reads the text of a button', () => {
  cy.visit('/cart');
  cy.get('#checkout').then(($btn) => {
    cy.wrap($btn).invoke('text').should('contain', 'Checkout');
  });
});

it('compares the total with a computed value', () => {
  cy.visit('/cart');
  cy.get('#total').then(($el) => {
    const total = Number($el.text().replace('$', ''));
    expect(total).to.be.greaterThan(20);
  });
});

it('logs in on the auth domain', () => {
  cy.visit('/');
  cy.contains('Sign in').click();
  cy.origin('https://auth.example.com', () => {
    cy.get('#username').type('ada');
    cy.get('#password').type('secret');
  });
});

